import type { Meta, StoryObj } from "@storybook/vue3";
import { KozmosButton, KozmosSpinner } from "../../index";

/**
 * Vue's Spinner: the stories React's has, with the same names, each inside
 * the KozmosThemeProvider the Storybook's decorator gives every story.
 * React's are drawn by their own renders, and so are these;
 * test/parity/spinner.parity.spec.ts holds each to React's. Generated by
 * `port Spinner`; written by hand.
 */
const meta: Meta<typeof KozmosSpinner> = {
  title: "Vue/Core/Feedback/Spinner",
  component: KozmosSpinner,
};

export default meta;
type Story = StoryObj<typeof KozmosSpinner>;

export const Default: Story = {
  render: () => ({
    components: { KozmosSpinner },
    template: `<KozmosSpinner />`,
  }),
};

export const Small: Story = {
  render: () => ({
    components: { KozmosSpinner },
    template: `<KozmosSpinner size="sm" />`,
  }),
};

export const Large: Story = {
  render: () => ({
    components: { KozmosSpinner },
    template: `<KozmosSpinner size="lg" />`,
  }),
};

/** The four sizes: 16, 24, 32 and 48, as iOS, Android and Figma draw them. */
export const EverySize: Story = {
  render: () => ({
    components: { KozmosSpinner },
    template: `
      <div class="flex items-end gap-4">
        <KozmosSpinner size="sm" label="Loading, small" />
        <KozmosSpinner size="md" label="Loading, medium" />
        <KozmosSpinner size="lg" label="Loading, large" />
        <KozmosSpinner size="xl" label="Loading, extra large" />
      </div>
    `,
  }),
};

/**
 * The same arc inside a control that already says it is busy: Button
 * draws it directly rather than nesting a Spinner, as React's does.
 */
export const InAButton: Story = {
  render: () => ({
    components: { KozmosButton },
    template: `<KozmosButton is-loading>Saving</KozmosButton>`,
  }),
};
